fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    // For each string in `a`, produce a Vec<String> of its lines according to keepends.
    a.into_iter()
        .map(|s| {
            // If keepends is true, split with line-endings retained
            if keepends {
                // Custom logic to split lines while keeping endings
                let mut lines = Vec::new();
                let mut start = 0;
                let bytes = s.as_bytes();
                let len = bytes.len();

                for i in 0..len {
                    if bytes[i] == b'\n' {
                        // Include the newline character in the line
                        let end = i + 1;
                        lines.push(s[start..end].to_string());
                        start = end;
                    } else if bytes[i] == b'\r' {
                        // Check if \r is followed by \n for Windows line-endings
                        if i + 1 < len && bytes[i + 1] == b'\n' {
                            let end = i + 2;
                            lines.push(s[start..end].to_string());
                            start = end;
                        } else {
                            // Just \r alone as line ending
                            let end = i + 1;
                            lines.push(s[start..end].to_string());
                            start = end;
                        }
                    }
                }

                // Add any remaining substring after the last line-ending, if non-empty
                if start < len {
                    lines.push(s[start..len].to_string());
                }
                // If the string ends exactly with line ending, we have no trailing empty substring,
                // and lines is non-empty due to input being non-empty.
                lines
            } else {
                // keepends is false: split on \n or \r\n or \r, discarding line endings
                // Use built-in split with lines functionality removing endings
                // But it does not split on \r alone, so do custom splitting on all
                let mut lines = Vec::new();
                let mut start = 0;
                let bytes = s.as_bytes();
                let len = bytes.len();

                for i in 0..len {
                    if bytes[i] == b'\n' {
                        // This covers \n and \r\n because if \r exists before \n we already skipped it
                        // substring excludes line endings
                        lines.push(s[start..i].to_string());
                        start = i + 1;
                    } else if bytes[i] == b'\r' {
                        // \r alone line ending
                        lines.push(s[start..i].to_string());
                        start = i + 1;
                    }
                }

                // Add remaining segment after last line ending
                if start <= len {
                    lines.push(s[start..len].to_string());
                }

                // It's guaranteed input string is non-empty so lines will be non-empty with at least one string
                lines
            }
        })
        .collect()
}